117	impl AnyWeakView {
118	    /// Upgrade to a strong `AnyView` handle, if the view is still alive.
119	    pub fn upgrade(&self) -> Option<AnyView> {
120	        let entity = self.entity.upgrade()?;
121	        Some(AnyView {
122	            entity,
123	            render: self.render,
124	        })
125	    }
126	}
