143	impl std::fmt::Debug for AnyWeakView {
144	    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
145	        f.debug_struct("AnyWeakView")
146	            .field("entity_id", &self.entity.entity_id)
